        self.assertEqual(run(['3', '1', '2']), {'n': 3, 'lo': 0, 'hi': 3, 'ratio': 1.5})
    def test_case_01(self):
        self.assertEqual(run(['10', '0', '7', 'x']), {'n': 4, 'lo': 0, 'hi': 4, 'ratio': 2.0})
    def test_case_02(self):
        self.assertEqual(run([' 5 ', '-2', '8']), {'n': 3, 'lo': 0, 'hi': 3, 'ratio': 1.5})
    def test_case_03(self):
        self.assertEqual(run(['4:2', '9:1', 'bad']), {'n': 3, 'lo': 0, 'hi': 3, 'ratio': 1.5})
    def test_case_04(self):
        self.assertEqual(run(['12', '12', '1']), {'n': 3, 'lo': 0, 'hi': 3, 'ratio': 1.5})
    def test_case_05(self):
        self.assertEqual(run(['0']), {'n': 1, 'lo': 0, 'hi': 1, 'ratio': 0.5})
    def test_case_06(self):
        self.assertEqual(run(['6', '6', '6', '6']), {'n': 4, 'lo': 0, 'hi': 4, 'ratio': 2.0})
